import sys

def solve():
    # Read all tokens from standard input efficiently
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T_str = next(iterator)
    except StopIteration:
        return
    T = int(T_str)

    out = []

    for _ in range(T):
        N = int(next(iterator))

        # Read the 2N elements of the array A
        A = [int(next(iterator)) for _ in range(2 * N)]

        # Determine all 'bad' elements which are already adjacent
        bad = set()
        for i in range(2 * N - 1):
            if A[i] == A[i+1]:
                bad.add(A[i])

        # Base mapping to store tuples (u, v) as unique integers to optimize memory & time
        N_plus_1 = N + 1

        pair_min = {}
        pair_max = {}

        for i in range(2 * N - 1):
            u = A[i]
            v = A[i+1]

            if u != v and u not in bad and v not in bad:
                # Ensure ordered pairs so that (u, v) and (v, u) map to the same signature
                if u > v:
                    u, v = v, u

                # Signature for the pair mapped to a uniquely identifiable integer
                p = u * N_plus_1 + v

                if p not in pair_min:
                    pair_min[p] = i
                pair_max[p] = i  # Max index dynamically moves forward as `i` strictly climbs

        # Count configurations where identical couples are spread suitably apart
        ans = 0
        for p in pair_min:
            if pair_max[p] - pair_min[p] >= 2:
                ans += 1

        out.append(str(ans))

    # Flush output all at once
    sys.stdout.write('\n'.join(out) + '\n')

if __name__ == '__main__':
    solve()
